#ifndef __STEPPER_H
#define __STEPPER_H

#include <stdint.h>
#include "config/robot_config.h"

/*
 * Single STEP/DIR stepper output for a turntable.
 *
 *   PA0 -> STEP (TIM5_CH1)
 *   PA1 -> DIR  (plain GPIO)
 *
 * STEP pulses are generated by hardware; the TIM5 update interrupt only
 * counts them and shuts the timer down after the requested move.
 *
 * The power board header labels the same two lines STEP_PH (PA0) and STEP_EN
 * (PA1). The driver must be wired so PA0/PA1 are its 3.3 V logic inputs and
 * the motor supply ground is common with the board ground.
 */

typedef enum
{
    STEPPER_STATE_IDLE = 0,
    STEPPER_STATE_MOVING,
    STEPPER_STATE_RUNNING
} stepper_state_t;

typedef struct
{
    int32_t           position_steps;
    int32_t           target_steps;
    uint32_t          steps_per_rev;
    uint32_t          rate_hz;
    uint32_t          target_rate_hz;
    uint16_t          prescaler;
    uint16_t          period;
    uint16_t          compare;
    int8_t            direction;
    uint8_t           state;
} stepper_status_t;

/* Reported wiring of the STEP/DIR pair, for the PINS console command. */
typedef struct
{
    const char *step_port;
    uint8_t     step_pin;
    const char *step_timer;
    uint8_t     step_channel;
    const char *dir_port;
    uint8_t     dir_pin;
} stepper_wiring_t;

void          STEPPER_Init(void);

/* Relative move. Pulses are signed; rate_hz is clamped to the safe range. */
uint8_t       STEPPER_MovePulses(int32_t pulses, uint32_t rate_hz);

/* Relative turntable move. Positive degrees and CW both mean positive DIR. */
uint8_t       STEPPER_MoveDegrees(float degrees, float rpm);

/* Run until stopped. direction > 0 = positive, direction < 0 = negative. */
uint8_t       STEPPER_Run(int8_t direction, float rpm);

/* Stop immediately, parking STEP low. */
void          STEPPER_Stop(void);

/* Change the pulse count used by degree/RPM commands. */
void          STEPPER_SetStepsPerRev(uint32_t steps_per_rev);
uint32_t      STEPPER_GetStepsPerRev(void);
uint32_t      STEPPER_RpmToRate(float rpm);

/* Position is in driver pulses, not motor full steps. */
void          STEPPER_SetPositionPulses(int32_t position_steps);
void          STEPPER_Zero(void);

/*
 * Call from the control task. This only parks the STEP pin shortly after an
 * ISR-driven move completes; pulse generation itself does not use the task.
 */
void          STEPPER_Update(void);

void          STEPPER_GetStatus(stepper_status_t *out);
void          STEPPER_GetWiring(stepper_wiring_t *out);

/* Logic level currently driven on the DIR pin (1 = high). */
uint8_t       STEPPER_GetDirLevel(void);

/* Force the DIR pin while the driver is idle, for wiring checks. */
uint8_t       STEPPER_SetDirLevel(uint8_t level);

/* Force the STEP pin while the driver is idle, for wiring checks. */
uint8_t       STEPPER_SetStepLevel(uint8_t level);
uint8_t       STEPPER_GetStepLevel(void);

const char   *STEPPER_StateName(stepper_state_t state);

#endif /* __STEPPER_H */
